module radix2_div (
    input wire clk,
    input wire rst,
    input wire [7:0] dividend,
    input wire [7:0] divisor,
    input wire sign,
    input wire opn_valid,
    output reg res_valid,
    input wire res_ready,
    output wire [15:0] result
);

reg [15:0] SR;
reg [3:0] cnt;
reg [3:0] start_cnt;
reg [7:0] NEG_DIVISOR;

always @(posedge clk or posedge rst) begin
    if (rst) begin
        SR <= 0;
        cnt <= 0;
        start_cnt <= 0;
        NEG_DIVISOR <= 0;
        res_valid <= 0;
    end else if (opn_valid && !res_valid) begin
        if (sign) begin
            SR[7:0] <= dividend;
            NEG_DIVISOR[7:0] <= -divisor;
        end else begin
            SR[7:0] <= dividend;
            NEG_DIVISOR[7:0] <= divisor;
        end
        SR[15:8] <= 0;
        cnt <= 1;
        start_cnt <= 1;
        res_valid <= 1;
    end else if (start_cnt) begin
        if (cnt == 8) begin
            cnt <= 0;
            start_cnt <= 0;
            res_valid <= 0;
        end else begin
            cnt <= cnt + 1;
            if (SR >= NEG_DIVISOR) begin
                SR <= SR - NEG_DIVISOR;
                SR[15:8] <= SR[15:8] + 1;
            end
            SR = {SR[14:0], 1'b0};
        end
    end
end

assign result = SR;

endmodule
